import json,os,sys
h=os.environ["SBX_HOME"]
def walk(root):
    out={}
    for d,_,fs in os.walk(root):
        for f in fs:
            p=os.path.join(d,f)
            out[os.path.relpath(p,root)]=open(p,"rb").read()
    return out
L=walk(os.path.join(h,"compare","left")); R=walk(os.path.join(h,"compare","right"))
c={"different":0,"leftOnly":0,"rightOnly":0,"same":0}
for k in set(L)|set(R):
    if k in L and k in R: c["same" if L[k]==R[k] else "different"]+=1
    elif k in L: c["leftOnly"]+=1
    else: c["rightOnly"]+=1
got=((json.load(open(os.environ["STATE_FILE"])).get("compare") or {}).get("folder") or {}).get("counts") or {}
sys.exit(0 if all(got.get(k)==c[k] for k in ("different","leftOnly","same")) else 1)
'

